	// Keep lazy synthesis close to the samples the current frame needs.
	// A 2048-frame lookahead synthesized almost three 60 Hz audio frames
	// together at 44.1 kHz, creating periodic work bursts on the emulation
	// thread. Smaller batches preserve the synthesis order and exact PCM
	// while spreading that work across normal media advances.
	if target < current+256 {
		target = current + 256
	}
	decoded.samples = decoded.smaf.renderUntil(decoded.samples, target)
}

